import {client,configured,getItem}from './api.mjs?v=ms-2';
import {iconEl,mesoAmt,ago}from './checker.mjs?v=ms-2';
import {account,result}from './community-api.mjs';
const $=id=>document.getElementById(id),world=()=>$('world').value||'';
const el=(t,p={},...kids)=>{const e=Object.assign(document.createElement(t),p);e.append(...kids.filter(x=>x!=null));return e;};
const message=(text,error=false)=>{$('community-status').textContent=text;$('community-status').className='status'+(error?' error':'');};
const run=fn=>async e=>{e?.preventDefault();try{await fn();}catch(err){message(err.message,true);}};
const link=item=>el('a',{className:'item-link',href:'#item/'+item.id},iconEl(item,28),el('span',{textContent:item.name}));
async function requireAccount(){if(!configured())throw Error('Price database not connected.');const user=await account();if(!user)throw Error('Sign in by email under Player Stores to use account features.');return user;}
async function watchItem(item){await requireAccount();await result((await client()).from('watchlist').upsert({item_id:item.id,world:world(),stats:{}},{onConflict:'owner,item_id,world,stats',ignoreDuplicates:true}));window.dispatchEvent(new CustomEvent('mesoswatch:watched',{detail:item}));message(item.name+' added to your watchlist. Alerts use the selected world and exact captured stats.');}
window.addEventListener('mesoswatch:item',e=>{const item=e.detail;const button=el('button',{textContent:'Watch item',onclick:run(()=>watchItem(item))});$('ip-links').append(button);});
async function loadWatchlist(){
 await requireAccount();const sb=await client(),rows=await result(sb.from('watchlist').select('*,item:items(*)').order('created_at',{ascending:false}));
 $('watchlist-items').replaceChildren(...(rows.length?rows.map(r=>{const threshold=el('input',{type:'number',min:1,max:1e11,step:1,value:r.threshold||'',ariaLabel:'Price threshold in mesos',placeholder:'Optional threshold'}),direction=el('select',{ariaLabel:'Alert direction'},new Option('At or below','below',false,r.direction==='below'),new Option('At or above','above',false,r.direction==='above'));
 return el('li',{},link(r.item),el('small',{textContent:(r.world||'Unspecified world')+' · '+JSON.stringify(r.stats)}),threshold,direction,el('button',{textContent:'Save alert',onclick:run(async()=>{const n=threshold.value?Number(threshold.value):null;if(n!==null&&(!Number.isSafeInteger(n)||n<1||n>1e11))throw Error('Enter a positive whole mesos threshold.');await result(sb.from('watchlist').update({threshold:n,direction:direction.value}).eq('id',r.id));message('Alert saved. Checked while this site is open; no background notification promise.');})}),el('button',{textContent:'Remove',onclick:run(async()=>{await result(sb.from('watchlist').delete().eq('id',r.id));await loadWatchlist();})}));}):[el('li',{className:'empty',textContent:'Your watchlist is empty. Open an item and choose Watch item.'})]));
}
async function loadAlerts(){await requireAccount();const sb=await client();await result(sb.rpc('evaluate_price_alerts'));const rows=await result(sb.from('price_alert_events').select('*,watch:watchlist(item:items(*),world,stats)').order('created_at',{ascending:false}).limit(50));$('price-alerts').replaceChildren(...(rows.length?rows.map(r=>el('li',{},r.watch?.item?link(r.watch.item):el('span',{textContent:'Watched item'}),mesoAmt(Number(r.price).toLocaleString()),el('small',{textContent:ago(r.created_at)+' · '+(r.watch?.world||'Unspecified world')+' · observed asking price; confirm availability'}),el('button',{textContent:r.read_at?'Read':'Mark read',disabled:!!r.read_at,onclick:run(async()=>{await result(sb.from('price_alert_events').update({read_at:new Date().toISOString()}).eq('id',r.id));await loadAlerts();})}))):[el('li',{className:'empty',textContent:'No threshold alerts yet. New threshold crossings are recorded once, with a 30-minute cooldown.'})]));}
$('alerts-refresh').onclick=run(loadAlerts);
$('report-form').onsubmit=run(async()=>{await requireAccount();const kind=$('report-kind').value,id=$('report-target').value.trim(),reason=$('report-reason').value.trim();if(reason.length<10)throw Error('Explain the problem in at least 10 characters.');if(kind==='observation'&&(!/^\d+$/.test(id)||!Number.isSafeInteger(Number(id))))throw Error('Use a valid observation ID.');if(kind==='megaphone'&&!/^[0-9a-f-]{36}$/i.test(id))throw Error('Use a valid campaign ID.');await result((await client()).from('market_reports').insert({reason,...(kind==='observation'?{observation_id:Number(id)}:{megaphone_id:id})}));$('report-form').reset();message('Report submitted for admin review. No data was removed.');await loadReports();});
async function loadReports(){const user=await requireAccount(),sb=await client();const rows=await result(sb.from('market_reports').select('*').eq('reporter',user.id).order('created_at',{ascending:false}).limit(30));$('my-market-reports').replaceChildren(...rows.map(r=>el('li',{},el('span',{textContent:r.reason}),el('small',{textContent:r.status+' · '+ago(r.created_at)+(r.review_note?' · '+r.review_note:'')}))));}
async function loadReview(){
 if(!configured())return;const sb=await client();const {data:admin}=await sb.rpc('is_admin');$('platform-admin').hidden=!admin;if(!admin)return;
 const [reports,sales,cash]=await Promise.all([result(sb.from('market_reports').select('*').eq('status','open').order('created_at').limit(50)),result(sb.from('observations').select('id,item_id,item_name,price,qty,seen_at,world,confidence').eq('kind','sale').eq('verification_status','reported').order('seen_at',{ascending:false}).limit(50)),result(sb.from('cash_item_candidates').select('*').eq('status','pending').order('created_at').limit(50))]);
 $('admin-market-reports').replaceChildren(...reports.map(r=>{const reason=el('input',{placeholder:'Review note (10+ characters)',minLength:10});return el('li',{},el('span',{textContent:r.reason+' · '+(r.observation_id?'Observation #'+r.observation_id:'Campaign '+r.megaphone_id)}),reason,...['dismissed','actioned'].map(status=>el('button',{textContent:status,onclick:run(async()=>{await result(sb.rpc('review_market_report',{p_id:r.id,p_status:status,p_note:reason.value}));await loadReview();message('Report recorded. Use the evidence or campaign controls for any separate action.');})})));}));
 $('admin-cash-reviews').replaceChildren(...cash.map(c=>{const gid=el('input',{type:'number',min:1,placeholder:'Verified game item ID'}),source=el('input',{type:'url',placeholder:'Classic release source URL'}),review=el('textarea',{placeholder:'Evidence and review note (10+ characters)'});return el('li',{},el('b',{textContent:c.name}),el('small',{textContent:(c.nx_price===null?'Unknown NX price':c.nx_price+' NX')+' · '+c.category+' · '+c.source_note}),gid,source,review,...['accepted','rejected'].map(decision=>el('button',{textContent:decision,onclick:run(async()=>{await result(sb.rpc('review_cash_candidate',{p_id:c.id,p_decision:decision,p_game_id:gid.value?Number(gid.value):null,p_source:source.value,p_note:review.value}));await loadReview();})})));}));
 $('admin-sale-reviews').replaceChildren(...await Promise.all(sales.map(async r=>{const reason=el('textarea',{placeholder:'Independent supporting evidence and review reason (10+ characters)'}),item=await getItem(r.item_id);return el('li',{},link(item),mesoAmt(Number(r.price).toLocaleString()),el('small',{textContent:'Observation #'+r.id+' · ×'+r.qty+' · '+r.world+' · '+ago(r.seen_at)+' · OCR confidence '+(r.confidence??'unknown')}),reason,...['verified','rejected'].map(decision=>el('button',{textContent:decision==='verified'?'Verify with evidence':'Reject evidence',onclick:run(async()=>{await result(sb.rpc('review_observation',{p_id:r.id,p_decision:decision,p_reason:reason.value}));await loadReview();})})));})));
}
async function loadRooms(){if(!configured())return;const sb=await client();const [rooms,items]=await Promise.all([result(sb.rpc('recent_fm_rooms',{p_world:world()})),result(sb.from('visible_items').select('id,name,game_id,category,icon_path,last_verified_at').order('last_verified_at',{ascending:false,nullsFirst:false}).limit(8))]);$('recent-fm-rooms').replaceChildren(...(rooms.length?rooms.map(r=>el('li',{},el('b',{textContent:r.map+(r.channel?' · Ch '+r.channel:'')}),el('small',{textContent:ago(r.last_seen)+' · '+r.observations+' observations · '+r.contributors+' contributor accounts; not independent identities'}))):[el('li',{className:'empty',textContent:'No FM rooms observed in the last 24 hours.'})]));$('recent-catalog-items').replaceChildren(...items.map(r=>el('li',{},link(r),el('small',{textContent:(r.category==='cash'?'NX · ':'')+'verified '+ago(r.last_verified_at)}))));}
function storeAnalytics(){let rows=[];try{rows=JSON.parse(localStorage.getItem('mw-sales')||'[]');if(!Array.isArray(rows))rows=[];}catch{}const corroborated=rows.filter(r=>r.corroborated===true&&Number.isFinite(r.amount));$('personal-analytics').textContent=rows.length+' local detections · '+corroborated.length+' OCR-corroborated · '+corroborated.reduce((n,r)=>n+r.amount,0).toLocaleString()+' mesos corroborated total change. These are not independently reviewed trades. Export history before clearing browser data.';}
window.addEventListener('mesoswatch:view',e=>{const actions={watchlist:loadWatchlist,alerts:loadAlerts,reports:loadReports,settings:loadReview,checker:loadRooms,store:async()=>storeAnalytics()};if(actions[e.detail.view])run(actions[e.detail.view])();});
window.addEventListener('mesoswatch:observed',()=>{if(document.body.dataset.view==='alerts')run(loadAlerts)();});
const active={watchlist:loadWatchlist,alerts:loadAlerts,reports:loadReports,settings:loadReview,checker:loadRooms};if(active[document.body.dataset.view])run(active[document.body.dataset.view])();storeAnalytics();
setInterval(()=>{if(!document.hidden&&document.body.dataset.view==='alerts')run(loadAlerts)();},60000);

document.querySelectorAll('#catalog-categories button').forEach(button=>button.onclick=run(async()=>{if(!configured())throw Error('Catalog database not connected.');const rows=await result((await client()).from('visible_items').select('id,name,game_id,icon_path,category').eq('category',button.dataset.category).order('name').limit(50));$('catalog-category-items').replaceChildren(...(rows.length?rows.map(item=>el('li',{},link(item))):[el('li',{className:'empty',textContent:'No verified items available in this category yet.'})]));message('Showing up to 50 verified items in this category. Use search for the full catalog.');}));
